 1	import java.util.Arrays;
 2	import java.util.Objects;
 3	
 4	final class RadixSort {
 5	    private static final int RADIX = 10;
 6	    private static final int[] SAMPLE_VALUES = { 170, 45, 75, 90, 802, 24, 2, 66 };
 7	
 8	    private RadixSort() {
 9	        // Utility class.
10	    }
11	
12	    static void sort(int[] values) {
13	        Objects.requireNonNull(values, "values must not be null");
14	        if (values.length < 2) {
15	            return;
16	        }
17	
18	        int max = findMax(values);
19	        for (long exp = 1; max / exp > 0; exp *= RADIX) {
20	            countingSortByDigit(values, exp);
21	        }
22	    }
23	
24	    private static int findMax(int[] values) {
25	        int max = values[0];
26	        for (int i = 1; i < values.length; i++) {
27	            if (values[i] > max) {
28	                max = values[i];
29	            }
30	        }
31	        return max;
32	    }
33	
34	    private static void countingSortByDigit(int[] values, long exp) {
35	        int[] output = new int[values.length];
36	        int[] count = new int[RADIX];
37	
38	        for (int value : values) {
39	            count[digitAt(value, exp)]++;
40	        }
41	
42	        for (int i = 1; i < RADIX; i++) {
43	            count[i] += count[i - 1];
44	        }
45	
46	        for (int i = values.length - 1; i >= 0; i--) {
47	            int value = values[i];
48	            int digit = digitAt(value, exp);
49	            output[count[digit] - 1] = value;
50	            count[digit]--;
51	        }
52	
53	        System.arraycopy(output, 0, values, 0, values.length);
54	    }
55	
56	    private static int digitAt(int value, long exp) {
57	        return (int) ((value / exp) % RADIX);
58	    }
59	
60	    private static void printValues(int[] values) {
61	        System.out.println(Arrays.toString(values));
62	    }
63	
64	    public static void main(String[] args) {
65	        int[] values = SAMPLE_VALUES.clone();
66	
67	        sort(values);
68	        printValues(values);
69	    }
70	}
